/** One entry of src/data/photos.json (generated by scripts/build-photos.ts). */
export interface PhotoMeta {
  /** File name inside public/photos, for example "lane.jpg". */
  filename: string;
  /** Wall-clock ISO capture time, YYYY-MM-DDTHH:mm:ss, with no timezone. */
  date: string;
  width: number;
  height: number;
}

export interface Photo extends PhotoMeta {
  /** Public URL, for example "/photos/lane.jpg". */
  src: string;
  index: number;
}

/** Copy in src/data/letter.json. */
export interface LetterContent {
  /** Opening line, for example "Dear friend,". */
  readonly greeting: string;
  /** Body paragraphs, in reading order. */
  readonly paragraphs: readonly string[];
  /** Closing line above the signature. */
  readonly signoff: string;
  /** Short name or sign-off under the closing line. */
  readonly signature: string;
  /**
   * Optional https URL for the button at the end of the walk.
   * An empty string hides the button.
   */
  readonly surpriseUrl: string;
}
